function flashLoan(address token, uint256 amount, bytes memory data) external {
    uint256 balanceBefore = IERC20(token).balanceOf(address(this));
    require(balanceBefore >= amount, "Insufficient liquidity");

    // Transfer tokens to borrower
    IERC20(token).transfer(msg.sender, amount);

    // Execute callback
    require(IFlashLoanReceiver(msg.sender).onFlashLoan(token, amount, data) == 0, "Flash loan failed");

    // Verify repayment
    uint256 balanceAfter = IERC20(token).balanceOf(address(this));
    require(balanceAfter >= balanceBefore, "Flash loan not repaid");
}

contract Proxy is Ownable {
    address public implementation;

    function upgrade(address newImplementation) external onlyOwner {
        require(newImplementation != address(0), "Invalid implementation");
        implementation = newImplementation;
    }

    fallback() external payable {
        _delegate(implementation);
    }
}

function getPrice() public view returns (uint256) {
    (uint80 roundId, int256 price,, uint256 updatedAt,) = priceOracle.latestRoundData();
    require(roundId > 0, "Invalid round");
    require(price > 0, "Invalid price");
    require(block.timestamp - updatedAt <= MAX_STALENESS, "Price stale");
    return uint256(price);
}
